        "prod-cobro-title": "Cobro del evento (Stripe + DJ)",
        "prod-cobro-section-help":
            "Aquí defines el artista asignado, el pago acordado y el depósito requerido para cobrar el evento. Esta sección no cambia la cotización; solo prepara el cobro y la operación financiera.",
        "prod-cobro-intro": "Guarda el documento primero (crea/actualiza el lead). Luego envía el enlace de depósito (30% mín. $150) o libera el pago al DJ cuando el evento esté conforme.",
        "prod-cobro-event-date-lbl": "Fecha del evento",
