        "event-prod-h1": "Producción de Eventos y Servicios Audiovisuales para Venues, Llave en Mano",
        "event-prod-lead": "Producción de eventos a gran escala — audio, iluminación y montaje — construida sobre alianzas reales y continuas con venues en Miami-Dade, Broward y los Cayos de la Florida.",
        "upcoming-events-title": "Próximos Eventos",
        "upcoming-events-empty": "Por ahora no hay eventos con fecha única programados — vuelve pronto, o encuéntranos en una de nuestras residencias semanales abajo.",
        "upcoming-events-cta": "Entérate del próximo show",
        "ohw-badge": "Formato de Show Especial",
        "ohw-title": "One Hit Wonder",
        "ohw-desc": "Un concepto de show en vivo de DJMago305 armado enteramente con himnos de un solo hit — canciones que todos reconocen desde la primera nota, de cualquier generación y cultura. Pregunta por este formato para tu próximo evento.",
        "event-prod-faq-title": "Preguntas Frecuentes — Producción de Eventos",
        "event-prod-faq-q1": "¿Qué incluye la producción integral de eventos?",
        "event-prod-faq-a1": "La producción integral se apoya en nuestro catálogo de equipos — audio profesional, iluminación y pantallas LED, tarimas, carpas y efectos especiales — combinado con talento DJ/MC, ajustado a tu venue y evento.",
        "event-prod-faq-q2": "¿Cómo funcionan sus alianzas con venues?",
        "event-prod-faq-a2": "Mantenemos residencias semanales reales y activas en venues como Sundowners en Key Largo, Mojitos Calle 8 y El Valle Restaurant — eventos regulares donde nuestra producción y talento ya son el estándar de la casa.",
        "event-prod-faq-q3": "¿Con cuánta anticipación debemos reservar la producción del evento?",
        "event-prod-faq-a3": "Recomendamos reservar con la mayor anticipación posible, especialmente para fines de semana y temporada alta, para confirmar inventario de equipo, personal y coordinar el montaje con tu venue.",
        "event-prod-faq-q4": "¿Qué zonas cubren para producción de eventos?",
        "event-prod-faq-a4": "Cubrimos Miami-Dade y Broward County, además de los Cayos de la Florida, donde mantenemos una residencia semanal activa en Key Largo.",
        "event-prod-related-1": "¿Planeas un evento de destino en los Cayos? Mira nuestro ",
        "event-prod-related-1-link": "DJ de Destino en los Cayos de la Florida",
        "fk-related-3": " ¿Necesitas producción integral llave en mano? Nuestro equipo de ",
        "fk-related-3-link": "Producción de Eventos",
        "fk-related-3-suffix": " ya mantiene una residencia semanal en Sundowners, Key Largo.",
