        "tools-feature-health-title": "Salud y economía del artista",
        "tools-feature-health-desc": "Pestaña Flujo de Caja en tu perfil (todos los artistas): finanzas y métricas; solo tú lo ves. SoundForTips™ (cabina en vivo) es solo con MDJPRO de pago.",
        "tools-feature-health-teaser": "Cash Flow — economía privada del artista en la web: KPIs de ingresos, índice de salud profesional, extracto tipo banco y export fiscal. Solo tú lo ves. SoundForTips™ en cabina es aparte (PRO de pago).",
        "tools-feature-health-cta": "Explorar Cash Flow",
        "tools-feature-lr-title": "Load Root",
        "tools-feature-lr-teaser": "Load Root — indica a MDJPRO dónde está tu música master en el Mac. Marcador de seguridad macOS, una elección, 100% local. Obligatorio antes de Scan, Wizard y Tag Master.",
        "tools-feature-lr-cta": "Explorar Load Root",
        "tools-cf-eyebrow": "Cash Flow · Salud Profesional",
        "tools-cf-page-title": "Salud y economía del artista",
        "tools-cf-lead": "El panel privado de finanzas y rendimiento en Miami DJ Beat — ingresos, eventos, residencia y un índice de salud artística que va más allá de las reseñas públicas.",
        "tools-cf-page-value": "Todo artista del roster (LITE o PRO) accede a Flujo de Caja en su perfil o dashboard. Nadie más ve tus números: fans ven reseñas; tú ves ledger, KPIs, gráficas y extracto bancario. Cheques y pagos locales cuentan si los reflejas en leads o en el libro mayor.",
        "tools-cf-note": "Cash Flow vive en la web (no en la app Mac MDJPRO). Los movimientos reales entran vía dj_ledger en Supabase — Stripe, liberaciones staff y propinas SoundForTips™ aceptadas. Esta página es informativa; el panel operativo está en tu perfil.",
