        "coi-tc-title": "Permiso de uso de datos",
        "coi-tc-lead": "Para que el sistema de <b>Miami DJ Beat</b> trabaje a tu favor, necesitamos tu autorización para registrar y usar los datos de tu agenda con fines profesionales.",
        "coi-tc-li1": "Autorizas registrar tus contactos y fechas recurrentes (cumpleaños, aniversarios) para <b>generarte trabajo</b> y publicidad dirigida.",
        "coi-tc-li2": "Tu calendario es <b>personal e independiente</b>: el sistema te recuerda las fechas de tus contactos para gestionarte eventos.",
        "coi-tc-li3": "No accedes a la base de datos de <b>otros artistas</b>. Cada artista está aislado.",
        "coi-tc-li4": "Miami DJ Beat (Owner) consolida la información en el <b>calendario master</b> solo para gestionar eventos futuros.",
        "coi-tc-check": "He leído y acepto los términos y condiciones, y autorizo el uso profesional de mis datos.",
        "coi-tc-accept": "Aceptar y activar mi calendario",
        "coi-tc-cancel": "Ahora no",
        "tools-cf-mode1-title": "KPIs de ingresos",
        "tools-cf-mode1-desc": "Ingresos brutos, balance disponible, retiros, comisión de plataforma y ticket medio — con tendencia vs el periodo anterior (7d, 30d, 90d, vista anual).",
        "tools-cf-mode2-title": "Pipeline de eventos",
        "tools-cf-mode2-desc": "Eventos completados y pendientes desde tus leads asignados — actividad real en MDJB, no estimaciones de terceros.",
        "tools-cf-mode3-title": "Residencia y comunidad",
        "tools-cf-mode3-desc": "Días con residencia, turnos en agenda marcados residente y venues en perfil — señales de posicionamiento local en Miami y más allá.",
        "tools-cf-mode4-title": "Índice Salud Profesional",
        "tools-cf-mode4-desc": "Estrellas compuestas: reseñas de clientes + ecosistema (eventos, ledger, tips, referidos, residencia). Solo el dueño del perfil ve este índice en el hero privado.",
        "tools-cf-mode5-title": "Extracto tipo banco",
        "tools-cf-mode5-desc": "Rollups día, semana, mes y año (zona America/New_York) — gross, comisión y neto por cubo, con filtros por tipo de movimiento.",
        "tools-cf-mode6-title": "Export fiscal CSV",
        "tools-cf-mode6-desc": "Detalle crudo hasta 7 años para archivo contable — ledger + propinas SoundForTips™ aceptadas, descargable por año fiscal.",
        "tools-cf-flow-title": "Dónde encaja Cash Flow en MDJB",
        "tools-cf-flow1": "Iniciar sesión",
