        "tools-cf-flow4": "Rango + KPIs",
        "tools-cf-flow5": "Extracto + CSV",
        "tools-cf-page-not-title": "Qué no es Cash Flow",
        "tools-cf-page-not-1": "No es público — visitantes y otros DJs no ven tu pestaña Flujo ni tus KPIs.",
        "tools-cf-page-not-2": "No está en MDJPRO Mac — es módulo web SaaS de Miami DJ Beat.",
        "tools-cf-page-not-3": "No sustituye SoundForTips™ — la cabina en vivo y su pestaña PRO son productos aparte.",
        "tools-cf-page-not-4": "No importa efectivo off-platform solo — debes reflejarlo en leads o líneas del ledger.",
        "tools-cf-page-roadmap-title": "Hoy vs lo que viene",
        "tools-cf-page-roadmap-1": "<strong>Hoy:</strong> KPIs, gráficas Chart.js, extracto bancario y export CSV desde dj_ledger + SFT aceptadas.",
        "tools-cf-page-roadmap-2": "<strong>Tú:</strong> artista LITE o PRO — acceso completo al panel privado; PRO desbloquea SoundForTips™, no Cash Flow.",
