        "tools-cf-future": "Cash Flow es tu sala de control financiera en la web — claridad operativa, salud profesional compuesta y trazabilidad bancaria. Solo Miami DJ Beat conecta eventos, ledger y propinas en un solo panel privado.",
        "tools-cf-cta": "Abrir mi panel Flujo",
