        "tools-lr-eyebrow": "Load Root · Carpeta Master",
        "tools-lr-page-title": "Load Root",
        "tools-lr-lead": "El primer paso del Hub MDJPRO — señala dónde vive tu música master en el Mac. Un permiso macOS, un marcador de seguridad persistente, acceso local para Scan, Wizard y Tag Master.",
        "tools-lr-page-value": "Load Root no escanea ni mueve archivos: autoriza el sandbox de macOS sobre la carpeta que eliges y la registra como fuente en ScanStore. Todo el procesamiento sigue en tu disco — sin subida a la nube.",
        "tools-lr-note": "Flujo típico: Splash → Hub → Load Root → (Library Wizard / Tag Master) → Start Scan → Results. Requiere licencia Basic o Premium (no Trial). Si el bookmark caduca, ejecuta Load Root de nuevo.",
        "tools-lr-modes-title": "Seis pilares del módulo",
        "tools-lr-mode1-title": "Selector de carpeta master",
        "tools-lr-mode1-desc": "Panel macOS NSOpenPanel — solo directorios, una selección. Textos localizados en ES/EN y más idiomas vía LanguageManager.",
        "tools-lr-mode2-title": "Security-Scoped Bookmark",
        "tools-lr-mode2-desc": "Permiso persistente SSB — macOS recuerda la carpeta sin Full Disk Access. USB externos se autorizan cuando tú los añades.",
        "tools-lr-mode3-title": "Registro en ScanStore",
        "tools-lr-mode3-desc": "La ruta normalizada se guarda como Source con bookmarkData — base para Start Scan, sync Serato/Rekordbox/VDJ y escritura Tag Master.",
        "tools-lr-mode4-title": "Gate Basic / Premium",
        "tools-lr-mode4-desc": "Entitlement basicScan — artistas con plan Basic o Premium. Trial muestra candado y abre Settings; no es módulo Premium-only como Wizard.",
        "tools-lr-mode5-title": "Re-verificación y troubleshooting",
        "tools-lr-mode5-desc": "Bookmark stale o icono rojo de permisos → vuelve a Load Root. Manual §14: renovar el marcador SSB es la acción canónica.",
        "tools-lr-mode6-title": "Dependencia del ecosistema",
        "tools-lr-mode6-desc": "Wizard auto-setea target desde el primer source; Start Scan sin sources abre Load Root con autoScan; Tag Master puede añadir sources deshabilitados para ID3.",
        "tools-lr-flow-title": "Dónde encaja Load Root en MDJPRO",
        "tools-lr-flow1": "Hub",
        "tools-lr-flow2": "Load Root",
        "tools-lr-flow3": "Wizard / Tag Master",
        "tools-lr-flow4": "Start Scan",
        "tools-lr-flow5": "Results",
        "tools-lr-page-not-title": "Qué no hace Load Root",
        "tools-lr-page-not-1": "No escanea audio ni video — eso es Start Scan.",
        "tools-lr-page-not-2": "No despliega ADN de carpetas — eso es Library Wizard (Premium).",
        "tools-lr-page-not-3": "No edita ID3 — eso es Tag Master (Premium).",
        "tools-lr-page-not-4": "No sustituye permiso de volumen USB protegido — usa «Dar permiso al disco» en Results si aplica.",
        "tools-lr-page-roadmap-title": "Hoy vs lo que viene",
        "tools-lr-page-roadmap-1": "<strong>Hoy:</strong> panel localizado PERMISOS-007, feedback en statusLine, badge verde con conteo de sources.",
        "tools-lr-page-roadmap-2": "<strong>Tú:</strong> elige la carpeta raíz real de tu fonoteca — Serato, Rekordbox o VirtualDJ leen desde ahí.",
        "tools-lr-page-roadmap-3": "<strong>Próximo:</strong> hints inline en Hub (copy only, PERMISOS-007 Phase 2+) — sin cambiar el flujo Splash → Hub.",
        "tools-lr-page-table-row1-layer": "Load Root (Mac Hub)",
        "tools-lr-page-table-row1-status": "En producción",
        "tools-lr-page-table-row1-role": "Autorizar carpeta master local",
