        "vip-welcome-family": "¡Bienvenido a la familia de Miami DJ Beat! Es un honor tenerte aquí.",
        "dl-title": "Suscripción MDJPRO App",
        "dl-latest": "Descarga la App de Miami DJ Beat",
        "dl-version": "Versión:",
        "dl-size": "Tamaño:",
        "dl-platform": "Plataforma:",
        "dl-whats-new": "Novedades en",
        "dl-sys-req": "Requisitos del Sistema",
        "dl-mac": "Mac",
        "dl-win": "Windows",
        "dl-warning-macos": "Instalador oficial de Miami DJ Beat — <a href=\"#dl-mac-install-help\" style=\"color:#fff;text-decoration:underline;\">ver cómo instalar abajo</a>.",
        "dl-install-title": "Cómo instalar en Mac",
        "dl-install-intro": "Descarga el instalador y sigue estos pasos. MDJPRO lo publica Miami DJ Beat desde miamidjbeat.com.",
        "dl-install-step1": "<strong>Cierra MDJ PRO</strong> si está abierto (Cmd+Q).",
        "dl-install-step2": "Haz doble clic en <strong>MDJPRO V.x.pkg</strong> en tu carpeta Descargas.",
        "dl-install-step3": "Sigue el instalador de macOS e ingresa tu contraseña si te la pide.",
        "dl-install-step4": "Al terminar la instalación, <strong>MDJ PRO se abre automáticamente</strong>.",
        "dl-install-step5": "La primera vez que uses <strong>Load Root</strong> o escanees tu librería, macOS puede pedir permiso — pulsa <strong>Permitir</strong> y elige tu carpeta de música.",
        "dl-install-step6": "<strong>Opcional:</strong> clic derecho en el icono de MDJ PRO en el Dock → <strong>Opciones</strong> → <strong>Mantener en el Dock</strong> para acceso rápido.",
        "dl-install-support": "¿Necesitas ayuda? Escríbenos a <a href=\"mailto:miamidjbeat@gmail.com\">miamidjbeat@gmail.com</a>.",
        "dl-features-tab": "Funciones de MDJPRO",
        "feat-intro-title": "¿Qué es MDJPRO? El Software de Miami DJ Beat",
        "feat-intro-desc": "MDJPRO no es simplemente una 'carpeta de música'. Es una metodología de trabajo integral y una topología de archivos diseñada para DJs de alto calibre y producciones exigentes. Nacido de la necesidad de erradicar el desorden digital, MDJPRO estructura tu biblioteca bajo principios de Control de Riesgos y Memoria Muscular, convirtiendo tu repertorio en un arsenal a prueba de fallos.",
        "feat-wizard-title": "Library Wizard (6 Modos)",
        "feat-wizard-desc": "Estructura matricial definitiva. Tu música se aloja físicamente en 6 ecosistemas: Décadas (Clásicos), Internacional (Mundo), Por Géneros (Específico), Eventos Especiales (Bodas/Quinces), Mi Legado (Tus producciones) y Performance Set (Rutas de show en vivo). Di adiós a las listas interminables.",
        "feat-risk-title": "Sistema de Control de Riesgos",
        "feat-risk-desc": "Implementamos el protocolo semáforo corporativo: Rojo (Carpetas Maestro, intocables en campo), Amarillo (Carga semanal controlada) y Verde (Live Drops y peticiones). Este sistema bloquea la corrupción de la base de datos y garantiza el 0% de regresiones en librerías masivas de 100,000+ tracks.",
        "feat-sync-title": "Matriz de Sincronización",
        "feat-sync-desc": "MDJPRO actúa como la Única Fuente de Verdad (Single Source of Truth). Los archivos residen en un disco SSD externo maestro que sincroniza bi-direccionalmente con Pioneer Rekordbox y Serato DJ. Un solo análisis, cero duplicados. Tus Hot Cues y Beatgrids exportados impecablemente a las CDJ3000.",
        "feat-screenless-title": "DJing Sin Pantallas (Muscle Memory)",
        "feat-screenless-desc": "El diseño de 3-niveles de jerarquía permite que localices cualquier canción con máximo 3 giros de perilla. Entrenando la memoria muscular, levantas la vista de la laptop y te conectas visualmente con la pista de baile, elevando sustancialmente tu presencia escénica.",
        "feat-tags-title": "Diccionario Modular de Etiquetas",
        "feat-tags-desc": "Un revolucionario sistema de Tagging. Secciones por 1. Energía (Warmup, Peak, End), 2. Vibe (Romántico, Agresivo, Mainstream) y 3. Situación (Cena, Cocktail, Baile). Esto alimenta carpetas inteligentes que sugieren mágicamente la próxima canción perfecta.",
        "feat-hw-title": "Ecosistema Hardware Elite",
        "feat-hw-desc": "Metodología 100% plug-and-play compatible con el hardware estándar de la industria (AlphaTheta, Pioneer DJ OPUS QUAD, DJM-V10). MDJPRO respeta las reglas de exportación USB HFS+ / FAT32 y arquitectura de Base de Datos Pioneer.",
        "btn-login": "ENTRAR",
        "btn-logout": "SALIR",
        "hero-title": "DJs de Miami y Producción de Eventos",
        "hero-sub": "DJs profesionales y producción de eventos para corporativos, privados y venues en toda Florida, con cobertura principal en Miami-Dade y Broward.",
        "menu-account": "MI PERFIL",
        "menu-rewards": "Recompensas",
