        "jobs-title": "Renta la App MDJPRO / Miami DJ Beat",
        "jobs-selection-subtitle": "Elige LITE o PRO, marca los roles que cubres y envía una sola solicitud.",
        "jobs-role-section-title": "TU ROL EN LA PLATAFORMA",
        "jobs-role-plaza-title": "PLAZAS DISPONIBLES",
        "jobs-role-section-sub": "Varias plazas a la vez: toca la tarjeta o el ✓. Pasa el ratón por la franja para pausar el carrusel.",
        "jobs-role-multiselect-hint": "Varias plazas a la vez: toca la tarjeta o el ✓. Pasa el ratón por la franja para pausar el carrusel.",
        "jobs-role-carousel-heading": "Selecciona tus categorías",
        "jobs-role-carousel-catalog-note-kicker": "Equipo Miami DJ Beat",
        "jobs-role-carousel-catalog-note-title": "Las nuevas plazas las definimos nosotros; no es un alta público desde aquí.",
        "jobs-role-carousel-catalog-note-sub": "Esta tarjeta es solo informativa — no hay casilla ni envío.",
