        "tools-tag-eyebrow": "Tag Master · Motor de Metadatos",
        "tools-tag-page-title": "Limpieza de Librería",
        "tools-tag-lead": "El cerebro de metadatos detrás de Limpieza de Librería — edición ID3 por lote, validación atómica e higiene profesional de tags en los tracks que ya indexaste en MDJPRO.",
        "tools-tag-page-value": "Donde Library Wizard construye los cajones, Tag Master etiqueta cada disco: título, artista, álbum, comentarios, carátula — limpio, verificado y escrito en disco de forma local. Sin nube. Tú confirmas cada Save.",
        "tools-tag-note": "Tag Master edita metadatos dentro de tus archivos. No despliega ADN de carpetas — eso es Library Wizard. Flujo típico: Load Root → Start Scan → limpia tags aquí → Save escribe ID3 físico.",
        "tools-tag-modes-title": "Seis pilares de trabajo",
        "tools-tag-mode1-title": "Editor ID3 por Lote",
        "tools-tag-mode1-desc": "Siete campos clave con validación en tiempo real — Título, Artista, Álbum, Comentarios y más. Draft tri-state para multi-selección.",
        "tools-tag-mode2-title": "Monitor Visual",
        "tools-tag-mode2-desc": "Carátula, ruta, bitrate, duración y tonalidad — columnas ajustables. Preview de audio y scrub de MP4 antes de confirmar.",
        "tools-tag-mode3-title": "Arsenal de Limpieza",
        "tools-tag-mode3-desc": "Magic Eraser, heurísticas Auto-Tag y limpieza de emojis — elimina basura y normaliza cadenas en lote.",
        "tools-tag-mode4-title": "Nombre de Archivo ↔ Tag",
        "tools-tag-mode4-desc": "Mapea patrones del filename a ID3 cuando los tags están vacíos — pools DJCity, feat. parsing incluido.",
        "tools-tag-mode5-title": "Sandbox de Importación",
        "tools-tag-mode5-desc": "Carga masiva desde Finder al editor — sesión enfocada independiente del último scan cuando lo necesitas.",
        "tools-tag-mode6-title": "Save & Distribution",
        "tools-tag-mode6-desc": "Escritura ID3 física con validación round-trip. MDJ Distribution previsualiza movimientos hacia tu ADN Wizard — tú confirmas antes de mover.",
        "tools-tag-flow-title": "Dónde encaja Tag Master en MDJPRO",
