        "reel-l6": "EL OFICIO", "reel-s6": "Disciplina. Conocimiento. Arte.",
        "reel-l7": "TU TIPO", "reel-s7": "¿Sabes cuál eres?",
        "reel-t1-h": "Bienvenido al<br><span style='color:var(--gold);'>Mundo DJ.</span>",
        "reel-t1-p1": "El mundo DJ no es solo música.<br>Es una <strong style='color:#fff;'>familia universal.</strong><br>Es disciplina. Es código. Es respeto. Es carácter.",
        "reel-t1-p2": "<strong style='color:var(--gold);'>Ser DJ es un privilegio.</strong><br>Y más que un privilegio… es una condición.<br>No todos reúnen los requisitos reales.",
        "reel-t1-p3": "Cada cabina es territorio sagrado. Cada evento es una misión. No por conveniencia — por <strong style='color:var(--gold);'>derecho ganado.</strong>",
        "reel-t2-h": "No se trata de<br><span style='color:var(--gold);'>mezclar canciones.</span>",
        "reel-t2-p1": "Se trata de <strong style='color:#fff;'>leer energía.</strong><br>De controlar emociones colectivas.<br>De administrar tiempos con precisión.",
        "reel-t2-p2": "El DJ que no estudia su arte<br>no es un artista — es un operador.",
        "reel-t2-p3": "Existen <strong style='color:#fff;'>7 tipos de DJ</strong> distintos. Cada uno con su entorno, su disciplina y sus reglas. Conocer cuál eres es el primer paso.",
        "reel-t3-h": "Es una condición.<br><span style='color:var(--gold);'>No un hobby.</span>",
        "reel-t3-p1": "No se trata de dinero fácil.<br>No se trata de fama superficial.<br>Ser DJ <em>no es usar los beneficios.</em><br><strong style='color:#fff;'>Es merecerlos.</strong>",
        "reel-t3-p2": "El <strong style='color:var(--gold);'>Mundo DJ</strong> es una familia que comparte disciplina, leyes y un esfuerzo que muy pocos están dispuestos a asumir.",
        "reel-t4-h": "Este curso<br><span style='color:var(--gold);'>existe para que eso nunca te pase.</span>",
        "reel-t4-p1": "Es muy poco profesional estar en un negocio sin saber de qué se trata.<br><strong style='color:#fff;'>Sin aprovechar cada etapa al máximo.</strong>",
        "reel-t4-p2": "Tu propósito te trajo aquí.<br>Ahora es momento de honrarlo.",
        "reel-t4-p3": "12 módulos. Cada uno con su propósito. Cada uno con su exigencia. <strong style='color:var(--gold);'>Comienza aquí.</strong>",
        "reel-t5-h": "La gente <span style='color:var(--gold);'>no olvida cómo la hiciste sentir.</span>",
        "reel-t5-p1": "El DJ que domina la energía de una sala<br>tiene el poder de crear <strong style='color:#fff;'>momentos que duran toda la vida.</strong>",
        "reel-t5-p2": "Eso no se improvisa.<br>Eso se aprende, se practica y se perfecciona.",
        "reel-t5-p3": "En Miami DJ Beat te enseñamos exactamente eso. <strong style='color:var(--gold);'>El arte de crear momentos.</strong>",
        "reel-t6-h": "Ser DJ es arte.<br><span style='color:var(--gold);'>Pero sobre todo, es <em>disciplina.</em></span>",
        "reel-t6-p1": "Muchos creen que ser DJ se aprende solo a mezclar canciones. <strong style='color:#fff;'>Error.</strong>",
        "reel-t6-i1": "🎯 Leer energía", "reel-t6-i2": "🧠 Controlar emociones", "reel-t6-i3": "⏱ Administrar tiempos", "reel-t6-i4": "🔥 Sostener reputación",
        "reel-t6-p2": "El mundo DJ no necesita más personas <em>tocando música</em>. <strong style='color:var(--gold);'>Necesita profesionales.</strong>",
        "reel-t7-h": "No todos nacen para<br><span style='color:var(--gold);'>el mismo tipo de DJ.</span><br><span style='font-size:clamp(18px,2.5vw,28px);color:#fff;'>Y eso está bien.</span>",
        "reel-t7-p1": "El error no es elegir uno.<br><strong style='color:#fff;'>El error es no saber cuál eres.</strong>",
        "reel-t7-p2": "Conocerte a ti mismo como DJ<br>es el primer acto profesional. <strong style='color:var(--gold);'>Comienza aquí.</strong>",
        // ── Courses Pillars & Quiz ─────────
        "course-pillar-1-title": "Disciplina",
        "course-pillar-1-desc": "El DJ que no se entrena, no crece. La disciplina diaria separa al aficionado del profesional.",
        "course-pillar-2-title": "Conocimiento",
        "course-pillar-2-desc": "Dominar la técnica, el equipo, el negocio y el protocolo. Saber de qué se trata cada etapa.",
        "course-pillar-3-title": "Propósito",
        "course-pillar-3-desc": "El DJ de élite no trabaja por dinero. Trabaja porque llevar la música a la gente es su razón de ser.",
        "course-quiz-badge": "📝 EVALUACIÓN · MÓDULO 1",
        "course-quiz-title": "Pon a prueba tu conocimiento",
        "course-quiz-desc": "30 preguntas sobre los 12 tipos de DJ profesional. Selecciona la opción correcta. Si fallas, se muestra la respuesta correcta antes de continuar.",
        "course-quiz-q-meta": "PREGUNTA {n} DE {t}",
