        "course-quiz-res-60": "Bien, pero repasa los tipos que fallaste",
        "course-quiz-res-0": "Necesitas estudiar más antes de continuar",
        "course-quiz-res-sub": "Respondiste correctamente {s} de {t} preguntas",
        "course-art-badge": "📖 LECTURA CULTURAL — NO ES EVALUADO",
        "course-art-title": "El Selecta: Cuando Jamaica<br><span style='color:#00e87a;'>Inventó el DJ</span>",
        "course-art-sub": "Historia pura. No es tema de examen — pero sí de respeto.",
        "course-art-quote": "\"En Jamaica, el DJ no mezcla — <em>selecciona</em>.<br>Y por eso se le llama <span style=\"color:#00e87a;\">Selecta.</span>\"",
        "course-art-h1": "El Origen: El Sound System",
        "course-art-p1": "En los años 50, en Jamaica, no existían clubs ni discotecas como las conocemos hoy. En cambio, los barrios organizaban fiestas al aire libre usando <strong style=\"color:#fff;\">Sound Systems</strong> — enormes equipos de audio montados en camiones o improvisados en calles y patios. Estos Sound Systems competían entre sí. El que tenía el sistema más potente y la mejor selección musical <strong style=\"color:#fff;\">ganaba la noche</strong> — y ganaba el respeto de la comunidad.",
        "course-art-h2": "El Selecta: DJ, Curador y Figura Social",
        "course-art-p2": "El hombre detrás del Sound System tenía dos roles distintos:",
        "course-art-card1-t": "🎵 EL SELECTA",
        "course-art-card1-d": "El que elegía los vinilos. Su poder no estaba en la técnica de mezcla sino en el <strong style=\"color:#fff;\">conocimiento profundo de su librería</strong>. Sabía qué canción poner en cada momento exacto.",
        "course-art-card2-t": "🎤 EL MC / DEEJAY",
        "course-art-card2-d": "El que tomaba el micrófono mientras el Selecta ponía la música. Improvisaba rimas, animaba al público, creaba energía. <strong style=\"color:#fff;\">El MC jamaicano es el padre del rap.</strong>",
        "course-art-pull-t": "LA SEÑAL MÁS FAMOSA DEL SOUND SYSTEM",
        "course-art-pull-q": "\"Pull up, Selecta!\"",
        "course-art-pull-d": "Cuando el público gritaba esto, le pedía al Selecta que rebobinara el disco y lo volviera a poner desde el inicio. Era la máxima validación — equivalente al bis de un concierto clásico.",
        "course-art-h3": "Por Qué Importa para Ti como DJ",
        "course-art-p3": "La separación entre <strong style=\"color:#fff;\">Selecta</strong> y <strong style=\"color:#fff;\">MC</strong> en Jamaica es exactamente la misma distinción que existe hoy entre nuestros roles de <span style=\"color:var(--gold);\">DJ Club Residente</span> y <span style=\"color:var(--gold);\">MC / Animador</span>. No son el mismo oficio. Nunca lo fueron. Nacieron separados por diseño.",
        "course-art-p4": "El Sound System jamaicano también fue el lugar donde nació el <strong style=\"color:#fff;\">dub</strong>, el <strong style=\"color:#fff;\">dancehall</strong>, el <strong style=\"color:#fff;\">reggaeton</strong> (vía Puerto Rico) y en muchos aspectos, el <strong style=\"color:#fff;\">hip-hop del Bronx</strong>. DJ Kool Herc, el fundador del hip-hop, era jamaicano. Llevó la cultura del Sound System a Nueva York.",
        "course-art-time-title": "LÍNEA DE TIEMPO: DEL SELECTA AL DJ MODERNO",
        "course-art-time-1950": "Sound Systems en Jamaica. El Selecta como figura de poder cultural y social.",
        "course-art-time-1967": "DJ Kool Herc llega de Jamaica a New York. Aplica la cultura Sound System en el Bronx.",
        "course-art-time-1973": "La fiesta del 11 de agosto en 1520 Sedgwick Ave — nace oficialmente el hip-hop y el DJ moderno.",
        "course-art-time-today-t": "Hoy",
        "course-art-time-today-d": "El MC / Animador y el DJ Residente siguen siendo dos roles distintos — aunque pocos lo saben.",
        "course-art-note": "<strong style=\"color:var(--gold);\">Nota del instructor:</strong> Este artículo no es materia de examen, pero sí es parte del código cultural que todo DJ profesional debe conocer. El respeto por la historia del oficio define la calidad del artista.",
