        "djtypes-title": "Tipos de DJ",
        "djtypes-intro": "Antes de tocar un mixer, debes entender algo crítico: no todos los DJs hacen lo mismo. Uno de los errores más comunes es querer estar en todos los escenarios sin dominar ninguno.",
        "djtypes-wedding-type": "Bodas · Quinces · Eventos sociales",
        "djtypes-wedding-quote": "El DJ que actúa como director de experiencia. Coordina entrada, brindis, primer baile y mantiene la energía del evento con precisión protocolar.",
        "djtypes-wedding-ideal": "✓ Ideal si buscas: elegancia, emoción y coordinación perfecta",
        "djtypes-club-type": "Clubs · Bares · Residencias nocturnas",
        "djtypes-club-quote": "Especialista en mantener la pista llena de principio a fin. Domina la lectura del público y la mezcla fluida para maximizar la energía del lugar.",
        "djtypes-club-ideal": "✓ Ideal si buscas: alta energía y pista de baile que no para",
        "djtypes-open-type": "Fiestas privadas · Corporativos · Brunchs",
        "djtypes-open-quote": "El DJ versátil. Fluye entre géneros — salsa, reggaeton, hip-hop, pop — leyendo la sala en tiempo real y adaptándose a cualquier audiencia.",
        "djtypes-open-ideal": "✓ Ideal si buscas: variedad musical y flexibilidad total",
        "djtypes-festival-type": "Festivales · Grandes eventos · Conciertos",
        "djtypes-festival-quote": "Diseñado para el escenario grande. Maneja multitudes masivas, producción en vivo y momentos de impacto máximo con setlists de alto octanaje.",
        "djtypes-festival-ideal": "✓ Ideal si buscas: impacto visual y sonoro a gran escala",
        "djtypes-corporate-type": "Lanzamientos · Convenciones · Networking",
        "djtypes-corporate-quote": "Imagen impecable y protocolo empresarial. El DJ más sobre-exigido en presentación — aquí tu presencia es el contrato.",
        "djtypes-corporate-ideal": "✓ Ideal si buscas: profesionalismo, elegancia ejecutiva y marca",
        "djtypes-animator-type": "Fiestas · Shows en vivo · Hora loca",
        "djtypes-animator-quote": "El showman. Combina DJ con animación, dinámicas y hora loca. El alma visible del evento — carisma genuino o no improvises este rol.",
        "djtypes-animator-ideal": "✓ Ideal si buscas: energía extrema, participación total del público",
