        "event-prod-h1": "Turnkey Event Production &amp; Venue Audio-Visual Services",
        "event-prod-lead": "Full-scale event production — audio, lighting, and staging — built on real, ongoing venue partnerships across Miami-Dade, Broward, and the Florida Keys.",
        "upcoming-events-title": "Upcoming Events",
        "upcoming-events-empty": "No single-date events are scheduled right now — check back soon, or catch us at one of our weekly residencies below.",
        "upcoming-events-cta": "Get notified about the next show",
        "ohw-badge": "Special Show Format",
        "ohw-title": "One Hit Wonder",
        "ohw-desc": "A live DJMago305 show concept built entirely around one-hit-wonder anthems — songs everyone recognizes from the first note, across every generation and culture. Ask about booking this format for your next event.",
        "event-prod-faq-title": "Event Production FAQ",
        "event-prod-faq-q1": "What's included in full event production?",
        "event-prod-faq-a1": "Full production draws on our equipment catalog — professional audio, lighting and LED screens, staging, tents, and special effects — combined with DJ/MC talent, sized to your venue and event.",
        "event-prod-faq-q2": "How do your venue partnerships work?",
        "event-prod-faq-a2": "We hold real, ongoing weekly residencies at venues including Sundowners in Key Largo, Mojitos Calle 8, and El Valle Restaurant — regular events where our production and talent are already the house standard.",
        "event-prod-faq-q3": "How far in advance should we book event production?",
        "event-prod-faq-a3": "We recommend booking as early as possible, especially for weekends and peak season, so we can confirm equipment inventory, staffing, and coordinate setup with your venue.",
        "event-prod-faq-q4": "What areas do you cover for event production?",
        "event-prod-faq-a4": "We cover Miami-Dade and Broward County, plus the Florida Keys, where we maintain an active weekly residency in Key Largo.",
        "event-prod-related-1": "Planning a destination event in the Keys? See our ",
