        "tools-feature-health-title": "Artist health & economics",
        "tools-feature-health-desc": "Cash Flow tab in your profile (all roster artists): revenue and metrics; visible only to you. SoundForTips™ (live booth) requires paid DJ PRO.",
        "tools-feature-health-teaser": "Cash Flow — private artist economics on the web: revenue KPIs, professional health index, bank-style statements, and tax export. Visible only to you. SoundForTips™ live booth is separate (paid PRO).",
        "tools-feature-health-cta": "Explore Cash Flow",
        "tools-feature-lr-title": "Load Root",
        "tools-feature-lr-teaser": "Load Root — point MDJPRO at your master music folder on Mac. macOS security bookmark, one pick, local-only. Required before Scan, Wizard, and Tag Master.",
        "tools-feature-lr-cta": "Explore Load Root",
        "tools-cf-eyebrow": "Cash Flow · Professional Health",
        "tools-cf-page-title": "Artist health & economics",
        "tools-cf-lead": "The private finance and performance panel on Miami DJ Beat — revenue, events, residency, and a professional health index that goes beyond public reviews.",
        "tools-cf-page-value": "Every roster artist (LITE or PRO) gets Cash Flow on profile or dashboard. No one else sees your numbers: fans see reviews; you see ledger, KPIs, charts, and bank-style statements. Checks and local pay count when you reflect them in leads or the ledger.",
        "tools-cf-note": "Cash Flow lives on the web (not in the MDJPRO Mac app). Real movements enter via dj_ledger in Supabase — Stripe, staff releases, and accepted SoundForTips™ tips. This page is informative; the live panel is on your profile.",
