        "coi-tc-title": "Data usage permission",
        "coi-tc-lead": "So the <b>Miami DJ Beat</b> system can work in your favor, we need your authorization to record and use your calendar data for professional purposes.",
        "coi-tc-li1": "You authorize recording your contacts and recurring dates (birthdays, anniversaries) to <b>generate work for you</b> and targeted advertising.",
        "coi-tc-li2": "Your calendar is <b>personal and independent</b>: the system reminds you of your contacts' dates so it can manage events for you.",
        "coi-tc-li3": "You don't access other <b>artists'</b> database. Each artist is isolated.",
        "coi-tc-li4": "Miami DJ Beat (Owner) consolidates the information in the <b>master calendar</b> only to manage future events.",
