        "tools-cf-mode1-desc": "Gross income, available balance, payouts, platform commission, and average ticket — with trend vs the previous period (7d, 30d, 90d, annual view).",
        "tools-cf-mode2-title": "Event pipeline",
        "tools-cf-mode2-desc": "Completed and pending events from your assigned leads — real MDJB activity, not third-party estimates.",
        "tools-cf-mode3-title": "Residency & community",
        "tools-cf-mode3-desc": "Residency days, resident slots in agenda, and venues on profile — local positioning signals in Miami and beyond.",
