        "tools-cf-page-not-title": "What Cash Flow is not",
        "tools-cf-page-not-1": "It is not public — visitors and other DJs do not see your Flow tab or KPIs.",
        "tools-cf-page-not-2": "It is not in MDJPRO Mac — it is a Miami DJ Beat web SaaS module.",
        "tools-cf-page-not-3": "It does not replace SoundForTips™ — live booth and its PRO tab are separate products.",
        "tools-cf-page-not-4": "It does not auto-import off-platform cash — you must reflect it in leads or ledger lines.",
        "tools-cf-page-roadmap-title": "Today vs what comes next",
        "tools-cf-page-roadmap-1": "<strong>Today:</strong> KPIs, Chart.js graphs, bank statement, and CSV export from dj_ledger + accepted SFT.",
        "tools-cf-page-roadmap-2": "<strong>You:</strong> LITE or PRO artist — full private panel access; PRO unlocks SoundForTips™, not Cash Flow.",
        "tools-cf-page-roadmap-3": "<strong>Next:</strong> TICKET-004 architecture — five financial layers per order with unified append-only ledger.",
        "tools-cf-page-table-row1-layer": "Cash Flow (web)",
        "tools-cf-page-table-row1-status": "In production",
        "tools-cf-page-table-row1-role": "Private artist economics",
        "tools-cf-page-table-row2-layer": "SoundForTips™",
        "tools-cf-page-table-row2-status": "Paid PRO",
