        "tools-cf-page-table-row3-status": "Foundation",
        "tools-cf-page-table-row3-role": "Append-only audit — source of truth",
        "tools-cf-future": "Cash Flow is your financial control room on the web — operational clarity, composite professional health, and bank-grade traceability. Only Miami DJ Beat connects events, ledger, and tips in one private panel.",
        "tools-cf-cta": "Open my Flow panel",
        "tools-cf-dashboard-link": "Dashboard Cash Flow →",
        "tools-cf-sft-link": "SoundForTips™ (PRO) →",
        "tools-lr-eyebrow": "Load Root · Master Folder",
        "tools-lr-page-title": "Load Root",
        "tools-lr-lead": "The first step on the MDJPRO Hub — point at your master music folder on Mac. One macOS grant, one persistent security bookmark, local access for Scan, Wizard, and Tag Master.",
        "tools-lr-page-value": "Load Root does not scan or move files: it authorizes the macOS sandbox on the folder you pick and registers it as a ScanStore source. All processing stays on your drive — no cloud upload.",
        "tools-lr-note": "Typical flow: Splash → Hub → Load Root → (Library Wizard / Tag Master) → Start Scan → Results. Requires Basic or Premium license (not Trial). If the bookmark goes stale, run Load Root again.",
        "tools-lr-modes-title": "Six module pillars",
        "tools-lr-mode1-title": "Master folder picker",
        "tools-lr-mode1-desc": "macOS NSOpenPanel — directories only, single selection. Localized copy in EN/ES and more languages via LanguageManager.",
        "tools-lr-mode2-title": "Security-Scoped Bookmark",
        "tools-lr-mode2-desc": "Persistent SSB permission — macOS remembers your folder without Full Disk Access. External USB is authorized when you add it.",
        "tools-lr-mode3-title": "ScanStore registration",
        "tools-lr-mode3-desc": "Normalized path saved as Source with bookmarkData — foundation for Start Scan, Serato/Rekordbox/VDJ sync, and Tag Master writes.",
        "tools-lr-mode4-title": "Basic / Premium gate",
        "tools-lr-mode4-desc": "basicScan entitlement — Basic or Premium plans. Trial shows lock and opens Settings; not Premium-only like Wizard.",
        "tools-lr-mode5-title": "Re-verification & troubleshooting",
        "tools-lr-mode5-desc": "Stale bookmark or red permission icon → run Load Root again. Manual §14: renewing the SSB marker is the canonical fix.",
        "tools-lr-mode6-title": "Ecosystem dependency",
        "tools-lr-mode6-desc": "Wizard auto-sets target from first source; Start Scan with no sources opens Load Root with autoScan; Tag Master may add disabled sources for ID3 access.",
        "tools-lr-flow-title": "Where Load Root sits in MDJPRO",
        "tools-lr-flow1": "Hub",
        "tools-lr-flow2": "Load Root",
        "tools-lr-flow3": "Wizard / Tag Master",
        "tools-lr-flow4": "Start Scan",
        "tools-lr-flow5": "Results",
        "tools-lr-page-not-title": "What Load Root does not do",
        "tools-lr-page-not-1": "It does not scan audio or video — that is Start Scan.",
        "tools-lr-page-not-2": "It does not deploy folder DNA — that is Library Wizard (Premium).",
        "tools-lr-page-not-3": "It does not edit ID3 — that is Tag Master (Premium).",
        "tools-lr-page-not-4": "It does not replace protected USB volume permission — use Grant Disk Access on Results when needed.",
        "tools-lr-page-roadmap-title": "Today vs what comes next",
        "tools-lr-page-roadmap-1": "<strong>Today:</strong> localized PERMISOS-007 panel, statusLine feedback, green badge with source count.",
        "tools-lr-page-roadmap-2": "<strong>You:</strong> pick the real root of your library — Serato, Rekordbox, or VirtualDJ read from there.",
        "tools-lr-page-roadmap-3": "<strong>Next:</strong> inline Hub hints (copy only, PERMISOS-007 Phase 2+) — Splash → Hub flow unchanged.",
        "tools-lr-page-table-row1-layer": "Load Root (Mac Hub)",
        "tools-lr-page-table-row1-status": "In production",
        "tools-lr-page-table-row1-role": "Authorize local master folder",
        "tools-lr-page-table-row2-layer": "Start Scan",
        "tools-lr-page-table-row2-status": "Next step",
        "tools-lr-page-table-row2-role": "Index enabled sources only",
        "tools-lr-page-table-row3-layer": "Wizard + Tag Master",
        "tools-lr-page-table-row3-status": "Premium",
        "tools-lr-page-table-row3-role": "Structure and metadata after root",
        "tools-lr-future": "Load Root is the front door to MDJPRO on your Mac — without it there is no scan, no Wizard DNA, and no Tag Master session with real context. One click, one permission, full local control.",
