        "dl-mac": "Mac",
        "dl-win": "Windows",
        "dl-warning-macos": "Official Miami DJ Beat installer — <a href=\"#dl-mac-install-help\" style=\"color:#fff;text-decoration:underline;\">see how to install below</a>.",
        "dl-install-title": "How to install on Mac",
        "dl-install-intro": "Download the installer, then follow these steps. MDJPRO is published by Miami DJ Beat from miamidjbeat.com.",
        "dl-install-step1": "<strong>Quit MDJ PRO</strong> if it is open (Cmd+Q).",
        "dl-install-step2": "Double-click <strong>MDJPRO V.x.pkg</strong> in your Downloads folder.",
        "dl-install-step3": "Follow the macOS installer and enter your Mac password if asked.",
        "dl-install-step4": "When installation finishes, <strong>MDJ PRO opens automatically</strong>.",
        "dl-install-step5": "The first time you use <strong>Load Root</strong> or scan your library, macOS may ask for permission — tap <strong>Allow</strong> and choose your music folder.",
        "dl-install-step6": "<strong>Optional:</strong> right-click the MDJ PRO icon in the Dock → <strong>Options</strong> → <strong>Keep in Dock</strong> for quick access.",
        "dl-install-support": "Need help? Email <a href=\"mailto:miamidjbeat@gmail.com\">miamidjbeat@gmail.com</a>.",
        "dl-features-tab": "MDJPRO Features",
        "feat-intro-title": "What is MDJPRO? The DJ Operating System",
        "feat-intro-desc": "MDJPRO is not just a 'music folder'. It is a comprehensive operational methodology and file topology designed for high-caliber DJs and demanding stage productions. Born from the need to eradicate digital clutter, MDJPRO structures your library under strict Risk Control and Muscle Memory principles, turning your repertoire into a fail-proof arsenal.",
        "feat-wizard-title": "Library Wizard (6 Modes)",
        "feat-wizard-desc": "The ultimate matrix structure. Your music is physically nested in 6 master ecosystems: Decades (Classics), International (World), By Genres (Specific), Special Events (Weddings/Quinces), My Legacy (Your productions), and Performance Set (Live show routes). Say goodbye to endless scrolling lists.",
        "feat-risk-title": "Risk Control System",
        "feat-risk-desc": "We implemented a corporate traffic-light protocol: Red (Master folders, untouchable in the field), Yellow (Weekly controlled loads), and Green (Live drops and field requests). This system completely blocks database corruption, guaranteeing 0% regressions even in massive 100,000+ track libraries.",
        "feat-sync-title": "Synchronization Matrix",
        "feat-sync-desc": "MDJPRO acts as the Single Source of Truth. Audio files reside on a master external SSD that bi-directionally syncs with both Pioneer Rekordbox and Serato DJ. One analysis, zero duplicates. Your Hot Cues and Beatgrids export flawlessly to industry-standard CDJ3000s.",
        "feat-screenless-title": "Screenless DJing (Muscle Memory)",
        "feat-screenless-desc": "Our 3-level folder hierarchy ensures you locate any track with a maximum of 3 knob twists. By training your muscle memory, you naturally lift your eyes from the laptop to visually connect with the dancefloor, substantially elevating your stage presence.",
        "feat-tags-title": "Modular Tag Dictionary",
        "feat-tags-desc": "A revolutionary tagging engine. Separated strictly by 1. Energy (Warmup, Peak, End), 2. Vibe (Romantic, Aggressive, Mainstream), and 3. Situation (Dinner, Cocktail, Dance). This metadata feeds SmartCrates that magically suggest your next perfect mix.",
        "feat-hw-title": "Elite Hardware Ecosystem",
        "feat-hw-desc": "A 100% plug-and-play methodology compatible with elite club hardware (AlphaTheta, Pioneer DJ OPUS QUAD, DJM-V10). MDJPRO respects USB HFS+/FAT32 formatting rules and Pioneer's database architecture, ensuring lightning-fast gig loading times.",
        "btn-login": "LOGIN",
        "btn-logout": "LOGOUT",
