        "tools-feature-clean-title": "Library Cleaning",
        "tools-feature-clean-desc": "Remove duplicates, fix metadata, and standardize tags in seconds.",
        "tools-feature-clean-teaser": "Tag Master — batch ID3, metadata hygiene, and local Save before the gig. The cleaning room your library deserves.",
        "tools-feature-clean-cta": "Explore Tag Master",
        "tools-tag-eyebrow": "Tag Master · Metadata Engine",
        "tools-tag-page-title": "Library Cleaning",
        "tools-tag-lead": "The metadata brain behind Library Cleaning — batch ID3 editing, atomic validation, and professional tag hygiene on tracks you already indexed in MDJPRO.",
        "tools-tag-page-value": "Where Library Wizard builds the shelves, Tag Master labels every record: title, artist, album, comments, cover art — cleaned, verified, and written back to disk locally. No cloud upload. You confirm every Save.",
        "tools-tag-note": "Tag Master edits metadata inside your files. It does not deploy folder DNA — that is Library Wizard. Typical flow: Load Root → Start Scan → clean tags here → Save writes physical ID3.",
        "tools-tag-modes-title": "Six workflow pillars",
        "tools-tag-mode1-title": "Batch ID3 Editor",
        "tools-tag-mode1-desc": "Seven core fields with real-time validation — Title, Artist, Album, Comments, and more. Tri-state draft for multi-select.",
        "tools-tag-mode2-title": "Visual Monitor",
        "tools-tag-mode2-desc": "Cover art, path, bitrate, duration, and key — adjustable columns. Audio preview and MP4 scrub before you commit.",
        "tools-tag-mode3-title": "Cleaning Arsenal",
        "tools-tag-mode3-desc": "Magic Eraser, Auto-Tag heuristics, and emoji cleanup — strip junk characters and normalize strings in batch.",
        "tools-tag-mode4-title": "Filename ↔ Tag",
        "tools-tag-mode4-desc": "Map filename patterns into ID3 when tags are empty or inconsistent — DJCity, pools, feat. parsing included.",
        "tools-tag-mode5-title": "Import Sandbox",
        "tools-tag-mode5-desc": "Bulk-load audio and video from Finder into the editor — focused session independent of the last scan when you need it.",
        "tools-tag-mode6-title": "Save & Distribution",
        "tools-tag-mode6-desc": "Physical ID3 write with round-trip validation. MDJ Distribution previews moves into your Wizard DNA — you confirm before anything moves.",
        "tools-tag-flow-title": "Where Tag Master sits in MDJPRO",
        "tools-tag-flow1": "Hub",
        "tools-tag-flow2": "Load Root",
        "tools-tag-flow3": "Start Scan",
        "tools-tag-flow4": "Tag Master",
        "tools-tag-flow5": "Results",
