        "tools-tag-page-not-1": "It does not deploy folder DNA — Library Wizard owns structure.",
        "tools-tag-page-not-2": "It does not silently rewrite your library — you confirm before Save.",
        "tools-tag-page-not-3": "It does not auto-commit when you change rows — draft changes need an explicit Save.",
        "tools-tag-page-not-4": "It requires MDJPRO Premium (tagMaster) — processing stays 100% local on your Mac.",
        "tools-tag-page-roadmap-title": "Today vs what comes next",
        "tools-tag-page-roadmap-1": "<strong>Today:</strong> batch ID3, cleaning tools, cover/video preview, verified local write.",
