        // ── courses.html ──────────────────
        "course-badge": "🏆 OFFICIAL MIAMI DJ BEAT CERTIFICATION",
        "course-hero-title": "Learn the Art of DJing<br><span style='color:var(--gold);'>From Scratch.</span><br><span style='color:var(--course-blue);'>Get Certified as a Professional.</span>",
        "course-hero-sub": "Everything you need to master — mixing technique, professional software, contract management, personal branding, and the mindset of an elite DJ.",
        "course-btn-access": "🚀 Access the Program",
        "course-btn-preview": "🎬 View Program",
        "course-btn-enroll": "I Want My DJ Certificate",
        "course-pay-loading": "Connecting to Stripe…",
        "course-pay-error": "Could not start payment: ",
        "course-pay-toast-success": "✅ Payment received. Check your email for the receipt; if course access is not visible within minutes, contact us.",
        "course-pay-toast-cancel": "Payment cancelled. You can try again anytime.",
        "course-stat-modules": "Modules",
        "course-stat-hours": "Hours of Content",
        "course-stat-online": "100% Online & Self-Paced",
        "course-stat-cert": "Official Certification",
        "course-stat-access": "Lifetime Access",
        "course-intro": "Welcome to the Miami DJ Beat Professional DJ Program.",
        "course-intro-p1": "This program is designed to train real DJs capable of performing in clubs, events, and professional stages.",
        "course-intro-p2": "Each module combines essential theory, technical practice, and evaluations that ensure true mastery of the DJ craft.",
        "course-access-restricted": "Full access to the program and evaluations is available only to enrolled members of the official program.",
        "course-premium-note": "This content is part of the certified professional program.",
        "course-evaluation-title": "Module Evaluation",
        "course-evaluation-desc": "Evaluations are designed to verify real mastery of the material before advancing to the next module.",
        "course-cert-final": "After completing the program and passing the official practical evaluation, you will receive the Miami DJ Beat professional certification.",
        "course-mod-1-title": "DJ Types: Identity and Market",
        "course-mod-1-desc": "Mindset, basic terminology, history, and the 7 unwritten laws of the Pro DJ.",
        "course-mod-2-title": "Real History of DJing",
        "course-mod-2-desc": "Pioneer and Denon consoles, controllers, mixers, cartridges. What to buy for your budget and style.",
        "course-mod-3-title": "Professional Library Organization",
        "course-mod-3-desc": "Serato DJ Pro, Rekordbox, Virtual DJ, and MDJPRO — advanced setup, workflows, and elite shortcuts.",
        "course-mod-4-title": "Mixing Technique",
        "course-mod-4-desc": "Beatmatching, EQ mixing, smooth transitions, phrasing, and how to build energy on the floor.",
        "course-mod-5-title": "MC & Floor Control",
        "course-mod-5-desc": "How to handle the mic, read the room, lead special moments (first dance, bridal march, crazy hour).",
        "course-mod-6-title": "Production & Lighting",
        "course-mod-6-desc": "DMX lighting control, sparks, visual effects, and creating experiences that multiply client satisfaction.",
        "course-mod-7-title": "Library Organization",
        "course-mod-7-desc": "Tag system, genres, decades, event lists. How to organize 50,000 songs to find any track in 5 seconds.",
        "course-mod-8-title": "Contracts & Quotes",
        "course-mod-8-desc": "How to draft contracts, handle deposits, cancellation clauses, and protect yourself legally.",
        "course-mod-9-title": "DJ Personal Marketing",
        "course-mod-9-desc": "How to build your brand on Instagram, TikTok, and Mixcloud. Content that attracts high-value clients.",
        "course-mod-10-title": "DJ Pricing & Finance",
        "course-mod-10-desc": "Setting rates, when to raise prices, handling payments, taxes, and building recurring income.",
        "course-mod-11-title": "Elite DJ Mindset",
        "course-mod-11-desc": "Managing nerves, technical unforeseen events, failure protocols, and staying in control under pressure.",
        "course-mod-12-title": "Final Exam + Certification",
        "course-mod-12-desc": "Practical and theoretical evaluation. Upon passing, receive your <strong style='color:var(--gold);'>Official Miami DJ Beat Pro DJ Certificate</strong>.",
        "course-tag-beginner": "BEGINNER",
        "course-tag-intermediate": "INTERMEDIATE",
        "course-tag-advanced": "ADVANCED",
        "course-tag-cert": "CERTIFICATION",
        "course-inc-title": "✅ What's Included?",
        "course-inc-vids": "40+ Hours of HD Video",
        "course-inc-vids-desc": "Recorded classes in a pro studio. Lifetime access, including updates.",
        "course-inc-docs": "Contracts & Templates",
