        "course-ins-bio": "More than <strong style='color:#fff;'>15 years of experience</strong> in weddings, clubs, residencies, and corporate events in Miami-Dade and Florida Keys. Creator of the MDJPRO system.",
        "course-ins-exp": "Events performed",
        "course-ins-years": "Career years",
