        // ── Manifesto Reel ────────────────
        "reel-l1": "DJ WORLD", "reel-s1": "Your purpose brought you here",
        "reel-l2": "DJ TYPES", "reel-s2": "7 archetypes. 1 destiny.",
        "reel-l3": "YOUR CODE", "reel-s3": "Discipline. Respect. Art.",
        "reel-l4": "START", "reel-s4": "The first step is today.",
        "reel-l5": "THE NIGHT", "reel-s5": "Create moments that last.",
        "reel-l6": "THE CRAFT", "reel-s6": "Discipline. Knowledge. Art.",
        "reel-l7": "YOUR TYPE", "reel-s7": "Do you know which one you are?",
        "reel-t1-h": "Welcome to the<br><span style='color:var(--gold);'>DJ World.</span>",
        "reel-t1-p1": "The DJ world is not just music.<br>It's a <strong style='color:#fff;'>universal family.</strong><br>It's discipline. It's code. It's respect. It's character.",
        "reel-t1-p2": "<strong style='color:var(--gold);'>Being a DJ is a privilege.</strong><br>And more than a privilege… it's a condition.<br>Not everyone meets the real requirements.",
        "reel-t1-p3": "Every booth is sacred territory. Every event is a mission. Not for convenience — by <strong style='color:var(--gold);'>earned right.</strong>",
        "reel-t2-h": "It's not about<br><span style='color:var(--gold);'>mixing songs.</span>",
        "reel-t2-p1": "It's about <strong style='color:#fff;'>reading energy.</strong><br>About controlling collective emotions.<br>About managing timing with precision.",
        "reel-t2-p2": "The DJ who doesn't study their art<br>is not an artist — they're an operator.",
        "reel-t2-p3": "There are <strong style='color:#fff;'>7 distinct types of DJ</strong>. Each with its setting, discipline, and rules. Knowing which one you are is the first step.",
        "reel-t3-h": "It's a condition.<br><span style='color:var(--gold);'>Not a hobby.</span>",
        "reel-t3-p1": "It's not about easy money.<br>It's not about superficial fame.<br>Being a DJ <em>isn't about using the perks.</em><br><strong style='color:#fff;'>It's about deserving them.</strong>",
        "reel-t3-p2": "The <strong style='color:var(--gold);'>DJ World</strong> is a family that shares discipline, laws, and an effort that very few are willing to take on.",
        "reel-t4-h": "This course<br><span style='color:var(--gold);'>exists so that never happens to you.</span>",
        "reel-t4-p1": "It's very unprofessional to be in a business without knowing what it's about.<br><strong style='color:#fff;'>Without taking full advantage of every stage.</strong>",
        "reel-t4-p2": "Your purpose brought you here.<br>Now it's time to honor it.",
        "reel-t4-p3": "12 modules. Each with its purpose. Each with its demand. <strong style='color:var(--gold);'>Start here.</strong>",
        "reel-t5-h": "People <span style='color:var(--gold);'>don't forget how you made them feel.</span>",
        "reel-t5-p1": "The DJ who masters the energy of a room<br>has the power to create <strong style='color:#fff;'>moments that last a lifetime.</strong>",
        "reel-t5-p2": "That isn't improvised.<br>That's learned, practiced, and perfected.",
        "reel-t5-p3": "At Miami DJ Beat we teach you exactly that. <strong style='color:var(--gold);'>The art of creating moments.</strong>",
        "reel-t6-h": "Being a DJ is art.<br><span style='color:var(--gold);'>But above all, it's <em>discipline.</em></span>",
        "reel-t6-p1": "Many believe being a DJ is just about learning to mix songs. <strong style='color:#fff;'>Error.</strong>",
        "reel-t6-i1": "🎯 Read energy", "reel-t6-i2": "🧠 Control emotions", "reel-t6-i3": "⏱ Manage timing", "reel-t6-i4": "🔥 Sustain reputation",
        "reel-t6-p2": "The DJ world doesn't need more people <em>playing music</em>. <strong style='color:var(--gold);'>It needs professionals.</strong>",
        "reel-t7-h": "Not everyone is born for<br><span style='color:var(--gold);'>the same type of DJ.</span><br><span style='font-size:clamp(18px,2.5vw,28px);color:#fff;'>And that's okay.</span>",
        "reel-t7-p1": "The mistake isn't choosing one.<br><strong style='color:#fff;'>The mistake is not knowing which one you are.</strong>",
        "reel-t7-p2": "Knowing yourself as a DJ<br>is the first professional act. <strong style='color:var(--gold);'>Start here.</strong>",
        // ── Courses Pillars & Quiz ─────────
        "course-pillar-1-title": "Discipline",
        "course-pillar-1-desc": "A DJ who doesn't train, doesn't grow. Daily discipline separates the amateur from the professional.",
        "course-pillar-2-title": "Knowledge",
        "course-pillar-2-desc": "Mastering technique, gear, business, and protocol. Knowing what each stage is about.",
        "course-pillar-3-title": "Purpose",
        "course-pillar-3-desc": "The elite DJ doesn't work for money. They work because bringing music to people is their reason for being.",
        "course-quiz-badge": "📝 ASSESSMENT · MODULE 1",
        "course-quiz-title": "Test your knowledge",
        "course-quiz-desc": "30 questions about the 12 types of professional DJ. Select the correct option. If you fail, the correct answer is shown before continuing.",
        "course-quiz-q-meta": "QUESTION {n} OF {t}",
        "course-quiz-next": "NEXT →",
        "course-quiz-result-btn": "SEE RESULT",
