        "djtypes-title": "DJ Types",
        "djtypes-intro": "Before touching a mixer, you need to understand something critical: not all DJs do the same thing. One of the most common mistakes is trying to be on every stage without mastering any of them.",
        "djtypes-wedding-type": "Weddings · Quinceañeras · Social Events",
        "djtypes-wedding-quote": "The DJ who acts as experience director. Coordinates entrance, toast, first dance, and keeps the event's energy on point with protocol precision.",
        "djtypes-wedding-ideal": "✓ Ideal if you want: elegance, emotion, and flawless coordination",
        "djtypes-club-type": "Clubs · Bars · Nightly Residencies",
        "djtypes-club-quote": "A specialist at keeping the floor packed from start to finish. Masters reading the crowd and seamless mixing to maximize the venue's energy.",
        "djtypes-club-ideal": "✓ Ideal if you want: high energy and a dance floor that never stops",
        "djtypes-open-type": "Private Parties · Corporate · Brunches",
        "djtypes-open-quote": "The versatile DJ. Flows between genres — salsa, reggaeton, hip-hop, pop — reading the room in real time and adapting to any crowd.",
        "djtypes-open-ideal": "✓ Ideal if you want: musical variety and total flexibility",
        "djtypes-festival-type": "Festivals · Major Events · Concerts",
        "djtypes-festival-quote": "Built for the big stage. Handles massive crowds, live production, and maximum-impact moments with high-octane setlists.",
        "djtypes-festival-ideal": "✓ Ideal if you want: large-scale visual and sonic impact",
        "djtypes-corporate-type": "Launches · Conventions · Networking",
        "djtypes-corporate-quote": "Impeccable image and corporate protocol. The most demanding presentation role — here, your presence is the contract.",
